78:             foreach ($keys as $key) {
79:                 $result[$key] = self::mergeRecursive($paramsValue[$key] ?? null, $filesValue[$key] ?? null);
80:             }
81: 
82:             return $result;
83:         }
84: 
85:         if (\is_array($paramsValue)) {
86:             return $paramsValue; // params has the precedence
87:         }
88: 
89:         if (self::isFileUpload($filesValue)) {
90:             return $filesValue; // if the array is a file upload field, it has the precedence
91:         }
92: 
93:         return $paramsValue;
94:     }
95: 
96:     /**
97:      * @param UploadedFile|array $value
98:      */
99:     private static function isFileUpload($value): bool
100:     {
101:         if ($value instanceof UploadedFile) {
102:             return true;
103:         }
104: 
105:         if (!\is_array($value) || !\in_array(\count($value), [5, 6], true)) {
106:             return false;
107:         }
108: 
109:         if (\array_key_exists('full_path', $value)) {
110:             unset($value['full_path']);
111:         }
112: 
113:         $keys = array_keys($value);
114:         sort($keys);
115: 
116:         return ['error', 'name', 'size', 'tmp_name', 'type'] === $keys;
117:     }
118: 
119:     private static function doesNotContainNonFileUploadArray(array $array): bool
120:     {
121:         foreach ($array as $value) {
122:             if (\is_array($value) && !self::isFileUpload($value)) {
123:                 return false;
124:             }
125:         }
126: 
127:         return true;
128:     }
129: }
